def _cart_has(p: "Probe", pid: str) -> bool:
    shop = getattr(p.world, "shop", None) if p.world else p.state
    items = getattr(getattr(shop, "cart", None), "items", []) or []
    return any(getattr(it, "product_id", "") == pid for it in items)


